, "sets_title": "حزم بسعر أقل", "upsell_show": true, "review_request_msg": "السلام عليكم {client}، نتمنى أن ملفات {name} أعجبتك 🤍 يسعدنا تقييمك في دقيقة من هنا: {link}"}, "proof": {"counts": true, "min_buyers": 3, "last": true, "favs": true, "min_favs": 5, "popup": true, "recent_days": 7, "total": true, "min_total": 20, "verified": true}, "contact": {"menu_show": true, "menu_home": true, "share_url": "https://a3r-om.github.io/huroof/", "wa_float": false, "wa_float_msg": "السلام عليكم، لدي استفسار عن ملفات {name}", "policy_show": true, "policy_title": "طريقة الاستلام والدفع", "policy_notes": "", "reviews_title": "آراء عملائنا", "reviews_share_btn": true, "reviews_share_text": "شاركنا رأيك", "reviews_share_msg": "السلام عليكم، هذا رأيي في ملفات {name}:", "reviews": [], "faq": [{"q": "كيف يصلني الملف؟", "a": "بعد ما ترسل الطلب على واتساب ونؤكد الدفع، نرسل لك الملفات في نفس المحادثة: أوراق العمل والقصص بصيغة PDF، والعروض التقديمية بصيغة PowerPoint."}, {"q": "هل أحتاج برنامجاً خاصاً لفتح الملفات؟", "a": "لا. ملفات PDF تفتح على أي جوال أو كمبيوتر، ويمكن طباعتها مباشرة أو من أي مكتبة. والعروض التقديمية تفتح في PowerPoint أو Keynote أو Google Slides."}, {"q": "هل أقدر أعدّل العروض التقديمية؟", "a": "نعم، العروض قابلة للتعديل بالكامل: النصوص والصور والألوان. وتحت كل شريحة ملاحظات للمعلمة تشرح طريقة تقديمها في الحصة."}, {"q": "هل الملفات ملوّنة أم أبيض وأسود؟", "a": "صفحات التلوين وأوراق العمل بالأبيض والأسود لتوفير الحبر، والقصص والشهادات واللوحات ملوّنة، وكلها تُطبع جيداً على أي طابعة."}, {"q": "ما مقاس الطباعة؟", "a": "كل ملفات PDF بمقاس A4، والشهادات وبعض جداول المعلمة بالعرض. والعروض التقديمية بمقاس الشاشة العريضة 16:9."}, {"q": "هل في الملفات حلول؟", "a": "نعم، ملفات المواد الدراسية الأربع، وجدول الضرب، والقراءة والفهم، والكسور، وكتاب «العب وتعلّم»، وبطاقات الأنشطة، كلها فيها صفحات حلول في آخرها."}, {"q": "هل أقدر أطبع الملف أكثر من مرة؟", "a": "نعم، تطبعه كلما احتجت لاستخدامك الشخصي أو لطلاب فصلك. لا يُسمح بإعادة بيع الملف أو نشره."}, {"q": "هل أقدر أجرّب قبل الشراء؟",